/**
 * What the action forms are made from: the JSON Schema of each tool (generated by `@acucraft/agent` from the engine's
 * own zod schemas, so a form can never ask for something the engine would not take). Pure — no DOM — so it is
 * tested on its own.
 */

export type JsonSchema = {
  type?: string | string[];
  description?: string;
  properties?: Record<string, JsonSchema>;
  required?: string[];
  additionalProperties?: boolean | JsonSchema;
  items?: JsonSchema;
  enum?: (string | number | boolean)[];
  const?: string | number | boolean;
  anyOf?: JsonSchema[];
  minimum?: number;
  maximum?: number;
  exclusiveMinimum?: number;
  maxLength?: number;
  minLength?: number;
  maxItems?: number;
  minItems?: number;
  default?: unknown;
};

/** The alternatives of a union, nested unions flattened (`move.to`: a room id, or one of five kinds of target). */
export function alternatives(schema: JsonSchema): JsonSchema[] {
  return (schema.anyOf ?? []).flatMap((alt) => (alt.anyOf ? alternatives(alt) : [alt]));
}

/** A union's alternative in a few words: what it asks for. */
export function alternativeLabel(alt: JsonSchema): string {
  if (alt.properties) {
    const required = alt.required?.length ? alt.required : Object.keys(alt.properties);
    return required.map(title).join(" + ");
  }
  if (alt.enum) return alt.enum.join(" / ");
  if (alt.const !== undefined) return String(alt.const);
  const type = Array.isArray(alt.type) ? alt.type.join(" or ") : (alt.type ?? "value");
  return type === "string" ? "an id or text" : type;
}

/** Which alternative a value fits best (the first whose required keys it has; a string, the scalar one). */
export function alternativeFor(schema: JsonSchema, value: unknown): number {
  const alts = alternatives(schema);
  if (value === undefined || value === null) return 0;
  if (typeof value !== "object") {
    const i = alts.findIndex((a) => !a.properties && (a.type === typeof value || (Array.isArray(a.type) && a.type.includes(typeof value))));
    return Math.max(0, i);
  }
  const keys = Object.keys(value as object);
  const scored = alts.map((a, i) => ({ i, ok: !!a.properties && (a.required ?? []).every((k) => keys.includes(k)) && keys.every((k) => k in a.properties!), n: (a.required ?? []).length }));
  const best = scored.filter((x) => x.ok).sort((x, y) => y.n - x.n)[0];
  return best ? best.i : 0;
}

/** A field's name as a label: `retentionMinutes` → "Retention minutes", `needle_id` → "Needle id". */
export function title(key: string): string {
  const words = key
    .replace(/\[\]$/, "")
    .replace(/[_-]+/g, " ")
    .replace(/([a-z0-9])([A-Z])/g, "$1 $2")
    .trim()
    .toLowerCase();
  return words ? words[0]!.toUpperCase() + words.slice(1) : key;
}

/** A long piece of writing (a note's history, a rationale) rather than a word or an id. */
export function isLong(schema: JsonSchema): boolean {
  return schema.type === "string" && !schema.enum && (schema.maxLength ?? 0) > 400;
}

/**
 * A form's value made ready to send: what was left empty is left out, so the engine's own defaults apply — an empty
 * string, an empty list, an object with nothing in it. Numbers stay numbers, `false` stays.
 */
export function prune(value: unknown): unknown {
  if (value === undefined || value === null) return undefined;
  if (typeof value === "string") return value.trim() === "" ? undefined : value;
  if (Array.isArray(value)) {
    const items = value.map(prune).filter((v) => v !== undefined);
    return items.length ? items : undefined;
  }
  if (typeof value === "object") {
    const out: Record<string, unknown> = {};
    for (const [k, v] of Object.entries(value as Record<string, unknown>)) {
      const kept = prune(v);
      if (kept !== undefined) out[k] = kept;
    }
    return Object.keys(out).length ? out : undefined;
  }
  return value;
}

/** A number typed into a field (empty: none; not a number: kept as text, for the engine to refuse with a reason). */
export function numberOf(text: string): number | string | undefined {
  const t = text.trim();
  if (t === "") return undefined;
  const n = Number(t);
  return Number.isFinite(n) ? n : t;
}
